const { createContext, useContext, useReducer } = React;
const CartStateContext = createContext(null);
const CartDispatchContext = createContext(null);

function reducer(state, action) {
  if (action.type === 'add') return { ...state, count: state.count + 1 };
  if (action.type === 'remove') return { ...state, count: Math.max(0, state.count - 1) };
  return state;
}
function CartProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, { count: 0 });
  return (
    <CartDispatchContext.Provider value={dispatch}>
      <CartStateContext.Provider value={state}>{children}</CartStateContext.Provider>
    </CartDispatchContext.Provider>
  );
}
function CartCount() { const state = useContext(CartStateContext); return <p>장바구니: {state.count}개</p>; }
function CartButtons() {
  const dispatch = useContext(CartDispatchContext);
  return <><button onClick={() => dispatch({ type: 'add' })}>추가</button><button onClick={() => dispatch({ type: 'remove' })}>삭제</button></>;
}
function App() { return <CartProvider><CartCount /><CartButtons /></CartProvider>; }

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

